package com.daniil.wristlens.phone;
import android.media.*;import android.os.Bundle;import android.view.Surface;import com.daniil.wristlens.core.RecordingTimeline;import java.io.*;import java.nio.*;import java.util.*;import java.util.concurrent.*;import java.util.function.Consumer;
/** Surface video + shared PCM microphone. Mute inserts silence without splitting the file. */
final class VideoRecorder {
 private final MicrophoneHub hub;private final Consumer<Exception> failure;private final RecordingTimeline timeline=new RecordingTimeline();
 private MediaCodec video,audio;private MediaMuxer muxer;private Surface surface;private final Object muxLock=new Object();private final List<Sample> pending=new ArrayList<>();
 private final BlockingQueue<Pcm> pcm=new ArrayBlockingQueue<>(128);private CountDownLatch drained;private int vt=-1,at=-1,pendingBytes;private long lastV=-1,lastA=-1;private volatile boolean running,stopping,released,waitKey=true;private boolean muted,muxStarted;private volatile Exception error;private long videoFrames;private volatile long keyAfterUs=Long.MIN_VALUE;
 private record Pcm(long time,short[] data){}private record Sample(boolean audio,byte[] data,long time,int flags){}
 VideoRecorder(FileDescriptor fd,Capabilities.VideoMode mode,String type,int rotation,boolean withAudio,boolean enabled,MicrophoneHub hub,Consumer<Exception> failure)throws Exception{
  this.hub=hub;this.failure=failure;muted=!enabled;
  try{String mime=type.equals("webm")?MediaFormat.MIMETYPE_VIDEO_VP8:type.equals("hevc")?MediaFormat.MIMETYPE_VIDEO_HEVC:MediaFormat.MIMETYPE_VIDEO_AVC;
   MediaFormat vf=MediaFormat.createVideoFormat(mime,mode.width(),mode.height());vf.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatSurface);vf.setInteger(MediaFormat.KEY_FRAME_RATE,mode.fps());vf.setInteger(MediaFormat.KEY_BIT_RATE,Math.max(2_000_000,(int)Math.min(60_000_000L,(long)mode.width()*mode.height()*mode.fps()/5)));vf.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,1);if(!type.equals("webm"))vf.setInteger(MediaFormat.KEY_MAX_B_FRAMES,0);
   String encoder=new MediaCodecList(MediaCodecList.REGULAR_CODECS).findEncoderForFormat(vf);if(encoder==null)throw new IOException("No compatible video encoder");video=MediaCodec.createByCodecName(encoder);video.configure(vf,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);surface=video.createInputSurface();
   if(withAudio){String am=type.equals("webm")?MediaFormat.MIMETYPE_AUDIO_VORBIS:MediaFormat.MIMETYPE_AUDIO_AAC;MediaFormat af=MediaFormat.createAudioFormat(am,48000,1);af.setInteger(MediaFormat.KEY_BIT_RATE,128000);af.setInteger(MediaFormat.KEY_MAX_INPUT_SIZE,8192);if(!type.equals("webm"))af.setInteger(MediaFormat.KEY_AAC_PROFILE,MediaCodecInfo.CodecProfileLevel.AACObjectLC);audio=MediaCodec.createEncoderByType(am);audio.configure(af,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);}
   muxer=new MediaMuxer(fd,type.equals("webm")?MediaMuxer.OutputFormat.MUXER_OUTPUT_WEBM:MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);if(!type.equals("webm"))muxer.setOrientationHint(rotation);
  }catch(Exception e){release();throw e;}
 }
 Surface getSurface(){return surface;}boolean hasAudio(){return audio!=null;}
 void prepare(){video.start();if(audio!=null)audio.start();drained=new CountDownLatch(audio==null?1:2);new Thread(this::videoLoop,"video-encode").start();if(audio!=null)new Thread(this::audioLoop,"audio-encode").start();}
 void start()throws Exception{if(error!=null)throw error;keyAfterUs=now();timeline.start(keyAfterUs,muted);running=true;keyframe();if(audio!=null)hub.add(this,new MicrophoneHub.Sink(){public void pcm(long time,short[] data){if(running&&!stopping&&!pcm.offer(new Pcm(time,data)))fail(new IOException("Audio encoder is too slow"));}public void error(Exception e){fail(e);}});}
 void muted(boolean value){timeline.mute(now(),value);muted=value;}
 void pause(){timeline.pause(now());}void resume(){keyAfterUs=now();waitKey=true;timeline.resume(keyAfterUs);keyframe();}
 private void keyframe(){Bundle b=new Bundle();b.putInt(MediaCodec.PARAMETER_KEY_REQUEST_SYNC_FRAME,0);video.setParameters(b);}
 private static long now(){return System.nanoTime()/1000;}
 private void fail(Exception e){if(error==null){error=e;failure.accept(e);}}
 private void videoLoop(){long shift=Long.MIN_VALUE;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();try{while(!released){int ix=video.dequeueOutputBuffer(info,10000);if(ix==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){format(false,video.getOutputFormat());continue;}if(ix<0)continue;try{if(info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){if(shift==Long.MIN_VALUE){long delta=now()-info.presentationTimeUs;shift=Math.abs(delta)>10_000_000?delta:0;}RecordingTimeline.Point p=timeline.at(info.presentationTimeUs+shift);boolean key=(info.flags&MediaCodec.BUFFER_FLAG_KEY_FRAME)!=0;if(p!=null&&(!waitKey||key&&info.presentationTimeUs+shift>=keyAfterUs)){waitKey=false;sample(false,video.getOutputBuffer(ix),info,p.timeUs());videoFrames++;}}if((info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0)break;}finally{video.releaseOutputBuffer(ix,false);}}}catch(Exception e){if(!released)fail(e);}finally{drained.countDown();}}
 private void audioLoop(){MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();Pcm block=null;RecordingTimeline.Pcm filtered=null;int pos=0;long endPts=0;boolean eos=false;try{while(!released){
  if(!eos){if(filtered==null){block=pcm.poll(5,TimeUnit.MILLISECONDS);if(block!=null){filtered=timeline.filter(block.time,block.data,48000);pos=0;if(filtered.samples().length==0)filtered=null;}}
   if(filtered!=null||stopping&&pcm.isEmpty()){int ix=audio.dequeueInputBuffer(10000);if(ix>=0){ByteBuffer in=audio.getInputBuffer(ix);if(in==null)throw new IOException("No audio input buffer");in.clear();in.order(ByteOrder.LITTLE_ENDIAN);if(filtered==null){audio.queueInputBuffer(ix,0,0,endPts,MediaCodec.BUFFER_FLAG_END_OF_STREAM);eos=true;}else{int count=Math.min(in.remaining()/2,filtered.samples().length-pos);if(count<=0)throw new IOException("Audio buffer too small");long pts=filtered.timeUs()+pos*1_000_000L/48000;for(int i=0;i<count;i++)in.putShort(filtered.samples()[pos+i]);audio.queueInputBuffer(ix,0,count*2,pts,0);pos+=count;endPts=filtered.timeUs()+pos*1_000_000L/48000;if(pos==filtered.samples().length)filtered=null;}}}
  }
  for(;;){int ix=audio.dequeueOutputBuffer(info,eos?10000:0);if(ix==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){format(true,audio.getOutputFormat());continue;}if(ix<0)break;boolean done=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;try{if(info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0)sample(true,audio.getOutputBuffer(ix),info,Math.max(0,info.presentationTimeUs));}finally{audio.releaseOutputBuffer(ix,false);}if(done)return;}
 }}catch(Exception e){if(!released)fail(e);}finally{drained.countDown();}}
 private void format(boolean isAudio,MediaFormat f)throws IOException{synchronized(muxLock){if(isAudio)at=muxer.addTrack(f);else vt=muxer.addTrack(f);if(vt>=0&&(audio==null||at>=0)){muxer.start();muxStarted=true;for(Sample s:pending)write(s);pending.clear();pendingBytes=0;}}}
 private void sample(boolean isAudio,ByteBuffer data,MediaCodec.BufferInfo info,long time)throws IOException{if(data==null)throw new IOException("No encoded buffer");byte[] bytes=new byte[info.size];ByteBuffer copy=data.duplicate();copy.position(info.offset);copy.limit(info.offset+info.size);copy.get(bytes);Sample s=new Sample(isAudio,bytes,time,info.flags&~MediaCodec.BUFFER_FLAG_END_OF_STREAM);synchronized(muxLock){if(muxStarted)write(s);else{pendingBytes+=bytes.length;if(pendingBytes>32*1024*1024)throw new IOException("Encoder format timed out");pending.add(s);}}}
 private void write(Sample s){long pts=Math.max(s.time,s.audio?lastA+1:lastV+1);MediaCodec.BufferInfo b=new MediaCodec.BufferInfo();b.set(0,s.data.length,pts,s.flags);muxer.writeSampleData(s.audio?at:vt,ByteBuffer.wrap(s.data),b);if(s.audio)lastA=pts;else lastV=pts;}
 void stop()throws Exception{timeline.stop(now());stopping=true;running=false;hub.remove(this);video.signalEndOfInputStream();if(!drained.await(8,TimeUnit.SECONDS))throw new IOException("Encoder stop timed out");if(error!=null)throw error;if(videoFrames==0)throw new IOException("No video frames");synchronized(muxLock){if(!muxStarted)throw new IOException("No output tracks");muxer.stop();muxStarted=false;}}
 void reset(){release();}
 void release(){if(released)return;released=true;running=false;hub.remove(this);if(drained!=null)try{drained.await(1,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}for(MediaCodec c:new MediaCodec[]{video,audio})if(c!=null){try{c.stop();}catch(Exception ignored){}try{c.release();}catch(Exception ignored){}}if(muxer!=null){try{if(muxStarted)muxer.stop();}catch(Exception ignored){}try{muxer.release();}catch(Exception ignored){}}if(surface!=null)surface.release();}
}
